dsh-island.usage:
import type { Context } from 'cordis'

export const inject = ['island']

export function apply(ctx: Context) {
  // 注册一个菜单项（出现在托盘右键菜单，图标 + 标题）
  ctx.island.registerMenuItem({
    id: 'my-plugin',
    title: '我的插件',
    icon: '🔧',
    action: () => {
      // 用户点击托盘菜单项时执行
      console.log('my-plugin clicked')
    },
  })
  // 插件卸载时自动注销（ctx 生命周期自动清理）
}

